// Store implements mm_client.StorageClient
func (mmStore *StorageClientMock) Store(ctx context.Context, blobID string, size int64, body io.Reader) (s1 string, err error) {
	mm_atomic.AddUint64(&mmStore.beforeStoreCounter, 1)
	defer mm_atomic.AddUint64(&mmStore.afterStoreCounter, 1)

	mmStore.t.Helper()

	if mmStore.inspectFuncStore != nil {
		mmStore.inspectFuncStore(ctx, blobID, size, body)
	}

	mm_params := StorageClientMockStoreParams{ctx, blobID, size, body}

	// Record call args
	mmStore.StoreMock.mutex.Lock()
	mmStore.StoreMock.callArgs = append(mmStore.StoreMock.callArgs, &mm_params)
	mmStore.StoreMock.mutex.Unlock()

	for _, e := range mmStore.StoreMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.s1, e.results.err
		}
	}

	if mmStore.StoreMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmStore.StoreMock.defaultExpectation.Counter, 1)
		mm_want := mmStore.StoreMock.defaultExpectation.params
		mm_want_ptrs := mmStore.StoreMock.defaultExpectation.paramPtrs

		mm_got := StorageClientMockStoreParams{ctx, blobID, size, body}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmStore.t.Errorf("StorageClientMock.Store got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmStore.StoreMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.blobID != nil && !minimock.Equal(*mm_want_ptrs.blobID, mm_got.blobID) {
				mmStore.t.Errorf("StorageClientMock.Store got unexpected parameter blobID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmStore.StoreMock.defaultExpectation.expectationOrigins.originBlobID, *mm_want_ptrs.blobID, mm_got.blobID, minimock.Diff(*mm_want_ptrs.blobID, mm_got.blobID))
			}

			if mm_want_ptrs.size != nil && !minimock.Equal(*mm_want_ptrs.size, mm_got.size) {
				mmStore.t.Errorf("StorageClientMock.Store got unexpected parameter size, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmStore.StoreMock.defaultExpectation.expectationOrigins.originSize, *mm_want_ptrs.size, mm_got.size, minimock.Diff(*mm_want_ptrs.size, mm_got.size))
			}

			if mm_want_ptrs.body != nil && !minimock.Equal(*mm_want_ptrs.body, mm_got.body) {
				mmStore.t.Errorf("StorageClientMock.Store got unexpected parameter body, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmStore.StoreMock.defaultExpectation.expectationOrigins.originBody, *mm_want_ptrs.body, mm_got.body, minimock.Diff(*mm_want_ptrs.body, mm_got.body))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmStore.t.Errorf("StorageClientMock.Store got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmStore.StoreMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmStore.StoreMock.defaultExpectation.results
		if mm_results == nil {
			mmStore.t.Fatal("No results are set for the StorageClientMock.Store")
		}
		return (*mm_results).s1, (*mm_results).err
	}
	if mmStore.funcStore != nil {
		return mmStore.funcStore(ctx, blobID, size, body)
	}
	mmStore.t.Fatalf("Unexpected call to StorageClientMock.Store. %v %v %v %v", ctx, blobID, size, body)
	return
}

